/**
 * Host-aware site icons. The Circle Hub and Athena share one deployment, so
 * /favicon.ico, /favicon.svg, /apple-touch-icon.png and /site.webmanifest are
 * served here instead of from public/: Athena hosts (meetathena.io and its
 * subdomains) get the Athena logo, every other host keeps the Circle icons
 * byte-for-byte as they were. Text-only tooling cannot commit binaries, so
 * the bytes live here as base64.
 */

type Asset = { type: string; body: string; base64: boolean };

// 0.8.8: Athena blue brand (mono-blue mark, 20 Oct 2026). Circle icons below are unchanged.
const ATHENA: Record<string, Asset> = {
  "/favicon.ico": { type: "image/x-icon", base64: true, body: "" },
  "/favicon.svg": { type: "image/svg+xml", base64: false, body: "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"54.5 1 720 720\" role=\"img\" aria-labelledby=\"title desc\"><title id=\"title\">Athena mark \u2014 mono-blue</title><desc id=\"desc\">Original outlined geometry preserved; recolored to the Athena preview website palette, 20 October 2026. Outlined artwork with no fonts or background.</desc><g id=\"athena-mark\"><path id=\"mark-1\" fill=\"#2563EB\" d=\"M395 140H540L260 582H108Z\"/><path id=\"mark-2\" fill=\"#2563EB\" d=\"M459 288H562L721 582H586Z\"/><path id=\"mark-3\" fill=\"#2563EB\" d=\"M393 404H499L517 443L337 493Z\"/></g></svg>" },
  "/apple-touch-icon.png": { type: "image/png", base64: true, body: "" },
  "/site.webmanifest": { type: "application/manifest+json", base64: false, body: "{\n  \"name\": \"Athena\",\n  \"short_name\": \"Athena\",\n  \"description\": \"Athena powered by ALP, construction agents.\",\n  \"start_url\": \"/\",\n  \"scope\": \"/\",\n  \"display\": \"standalone\",\n  \"background_color\": \"#FFFFFF\",\n  \"theme_color\": \"#2563EB\",\n  \"icons\": [\n    {\n      \"src\": \"/brand/athena/athena-mono-blue-64.png\",\n      \"sizes\": \"64x64\",\n      \"type\": \"image/png\",\n      \"purpose\": \"any\"\n    },\n    {\n      \"src\": \"/brand/athena/athena-mono-blue-512.png\",\n      \"sizes\": \"512x512\",\n      \"type\": \"image/png\",\n      \"purpose\": \"any\"\n    },\n    {\n      \"src\": \"/brand/athena/athena-mark-mono-blue.svg\",\n      \"sizes\": \"any\",\n      \"type\": \"image/svg+xml\",\n      \"purpose\": \"any\"\n    }\n  ]\n}" },
};

/** 0.8.8: blue Athena icon files, served on every host (connector icons and the sign-in email load them from either domain). */
const ATHENA_BRAND: Record<string, Asset> = {
  "/brand/athena/athena-mono-blue-64.png": { type: "image/png", base64: true, body: "" },
  "/brand/athena/athena-mono-blue-512.png": { type: "image/png", base64: true, body: "" },
};

const CIRCLE: Record<string, Asset> = {
  "/favicon.ico": { type: "image/x-icon", base64: true, body: "" },
  "/favicon.svg": { type: "image/svg+xml", base64: false, body: "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 64 64\"><rect width=\"64\" height=\"64\" fill=\"#F5F1E8\"/><text x=\"32\" y=\"47\" text-anchor=\"middle\" font-family=\"Arial,Helvetica,sans-serif\" font-weight=\"700\" font-size=\"44\" fill=\"#2B2B2B\">A</text></svg>\n" },
  "/apple-touch-icon.png": { type: "image/png", base64: true, body: "" },
  "/site.webmanifest": { type: "application/manifest+json", base64: false, body: "{\n  \"name\": \"Contractor Circle Command Center\",\n  \"short_name\": \"Contractor Circle\",\n  \"description\": \"The private member portal for Contractor Circle: live calls with Marshall, AOS access, replays, templates, Ask Marshall, and the operating process behind the projects.\",\n  \"start_url\": \"/\",\n  \"scope\": \"/\",\n  \"display\": \"standalone\",\n  \"background_color\": \"#F7F2EA\",\n  \"theme_color\": \"#F7F2EA\",\n  \"icons\": [\n    {\n      \"src\": \"/brand/circle-v1/app-icon-256.png\",\n      \"sizes\": \"256x256\",\n      \"type\": \"image/png\",\n      \"purpose\": \"any\"\n    },\n    {\n      \"src\": \"/brand/circle-v1/app-icon-512.png\",\n      \"sizes\": \"512x512\",\n      \"type\": \"image/png\",\n      \"purpose\": \"any maskable\"\n    }\n  ]\n}\n" },
};

export function isAthenaHost(hostname: string): boolean {
  const h = hostname.toLowerCase();
  return h === "meetathena.io" || h.endsWith(".meetathena.io");
}

function decode(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

/** Returns the icon response for GET/HEAD of a site-icon path, else null. */
export function siteIconResponse(request: Request): Response | null {
  const method = request.method.toUpperCase();
  if (method !== "GET" && method !== "HEAD") return null;
  const url = new URL(request.url);
  const set = isAthenaHost(url.hostname) ? ATHENA : CIRCLE;
  const brand = ATHENA_BRAND[url.pathname];
  const asset = brand ?? set[url.pathname];
  if (!asset) return null;
  const body = asset.base64 ? decode(asset.body) : asset.body;
  return new Response(method === "HEAD" ? null : (body as BodyInit), {
    status: 200,
    headers: {
      "content-type": asset.type,
      "cache-control": "public, max-age=3600",
      vary: "Host",
      // Connector icons are fetched cross-origin by ChatGPT and Claude. Circle icon headers are unchanged.
      ...(brand ? { "access-control-allow-origin": "*", "cross-origin-resource-policy": "cross-origin" } : {}),
    },
  });
}
